/* ============================================
   LearnForge — Corporate Website Stylesheet
   ============================================ */

/* --- Custom Properties --- */
:root {
  --primary: #4F46E5;
  --primary-light: #6366F1;
  --primary-dark: #3730A3;
  --primary-50: #EEF2FF;
  --primary-100: #E0E7FF;
  --primary-200: #C7D2FE;
  --accent: #E6FF32;
  --accent-dark: #C8E000;
  --coral: #FF6B6B;
  --coral-light: #FFE0E0;
  --green: #22C55E;
  --green-light: #DCFCE7;
  --neutral-900: #0F172A;
  --neutral-800: #1E293B;
  --neutral-700: #334155;
  --neutral-600: #475569;
  --neutral-500: #64748B;
  --neutral-400: #94A3B8;
  --neutral-300: #CBD5E1;
  --neutral-200: #E2E8F0;
  --neutral-100: #F1F5F9;
  --neutral-50: #F8FAFC;
  --white: #FFFFFF;
  --shadow-sm: 0 1px 2px rgba(15,23,42,0.05);
  --shadow: 0 1px 3px rgba(15,23,42,0.1), 0 1px 2px rgba(15,23,42,0.06);
  --shadow-md: 0 4px 6px -1px rgba(15,23,42,0.1), 0 2px 4px -2px rgba(15,23,42,0.1);
  --shadow-lg: 0 10px 15px -3px rgba(15,23,42,0.1), 0 4px 6px -4px rgba(15,23,42,0.1);
  --shadow-xl: 0 20px 25px -5px rgba(15,23,42,0.1), 0 8px 10px -6px rgba(15,23,42,0.1);
  --radius-sm: 6px;
  --radius: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;
  --font-heading: 'Plus Jakarta Sans', 'Inter', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --transition-slow: 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1200px;
  --nav-height: 72px;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }
body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--neutral-700);
  background: var(--white);
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul, ol { list-style: none; }
h1, h2, h3, h4, h5, h6 { font-family: var(--font-heading); color: var(--neutral-900); line-height: 1.2; }

/* --- Typography --- */
h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); font-weight: 800; letter-spacing: -0.025em; }
h2 { font-size: clamp(1.75rem, 4vw, 2.75rem); font-weight: 700; letter-spacing: -0.02em; }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.5rem); font-weight: 600; letter-spacing: -0.01em; }
h4 { font-size: 1.125rem; font-weight: 600; }
p { max-width: 65ch; }
.text-lg { font-size: 1.125rem; line-height: 1.7; }
.text-sm { font-size: 0.875rem; line-height: 1.5; }
.text-xs { font-size: 0.75rem; line-height: 1.5; }
.text-center { text-align: center; }

/* --- Layout --- */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}
.section {
  padding: 80px 0;
}
.section-sm { padding: 60px 0; }
.section-lg { padding: 100px 0; }
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }
.justify-between { justify-content: space-between; }
.gap-1 { gap: 8px; }
.gap-2 { gap: 16px; }
.gap-3 { gap: 24px; }
.gap-4 { gap: 32px; }
.gap-5 { gap: 48px; }

/* --- Scroll Animations --- */
.reveal {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.6s cubic-bezier(0.4, 0, 0.2, 1), transform 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}
.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--neutral-200);
  transition: box-shadow var(--transition);
}
.nav.scrolled {
  box-shadow: var(--shadow-md);
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--nav-height);
}
.nav-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
  letter-spacing: -0.03em;
  display: flex;
  align-items: center;
  gap: 8px;
}
.nav-logo span {
  color: var(--accent-dark);
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}
.nav-links a {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--neutral-600);
  transition: color var(--transition);
  position: relative;
}
.nav-links a:hover,
.nav-links a.active {
  color: var(--primary);
}
.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--primary);
  border-radius: 1px;
  transition: width var(--transition);
}
.nav-links a:hover::after,
.nav-links a.active::after {
  width: 100%;
}
.nav-cta {
  display: inline-flex;
  align-items: center;
  padding: 10px 24px;
  background: var(--primary);
  color: var(--white);
  font-weight: 600;
  font-size: 0.9rem;
  border-radius: var(--radius-full);
  transition: background var(--transition), transform var(--transition), box-shadow var(--transition);
}
.nav-cta:hover {
  background: var(--primary-dark);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(79,70,229,0.4);
}
.nav-mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}
.nav-mobile-toggle span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--neutral-700);
  border-radius: 2px;
  transition: transform var(--transition), opacity var(--transition);
}
.nav-mobile-toggle.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.nav-mobile-toggle.active span:nth-child(2) { opacity: 0; }
.nav-mobile-toggle.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

.nav-mobile-menu {
  display: none;
  position: fixed;
  top: var(--nav-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  padding: 24px;
  flex-direction: column;
  gap: 16px;
  z-index: 999;
}
.nav-mobile-menu.open {
  display: flex;
}
.nav-mobile-menu a {
  font-size: 1.1rem;
  font-weight: 500;
  color: var(--neutral-700);
  padding: 12px 0;
  border-bottom: 1px solid var(--neutral-100);
}
.nav-mobile-menu .nav-cta {
  text-align: center;
  justify-content: center;
  margin-top: 16px;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 32px;
  font-weight: 600;
  font-size: 1rem;
  border-radius: var(--radius-full);
  transition: all var(--transition);
  white-space: nowrap;
}
.btn-primary {
  background: var(--primary);
  color: var(--white);
}
.btn-primary:hover {
  background: var(--primary-dark);
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(79,70,229,0.35);
}
.btn-secondary {
  background: var(--white);
  color: var(--primary);
  border: 2px solid var(--primary-200);
}
.btn-secondary:hover {
  background: var(--primary-50);
  border-color: var(--primary);
  transform: translateY(-2px);
}
.btn-accent {
  background: var(--accent);
  color: var(--neutral-900);
}
.btn-accent:hover {
  background: var(--accent-dark);
  transform: translateY(-2px);
  box-shadow: 0 8px 20px rgba(230,255,50,0.3);
}
.btn-lg {
  padding: 18px 40px;
  font-size: 1.1rem;
}
.btn-sm {
  padding: 8px 20px;
  font-size: 0.875rem;
}

/* --- Hero Section --- */
.hero {
  padding-top: calc(var(--nav-height) + 60px);
  padding-bottom: 60px;
  background: linear-gradient(180deg, var(--primary-50) 0%, var(--white) 100%);
  position: relative;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  top: -200px;
  right: -200px;
  width: 600px;
  height: 600px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(79,70,229,0.08) 0%, transparent 70%);
  pointer-events: none;
}
.hero::after {
  content: '';
  position: absolute;
  bottom: -100px;
  left: -150px;
  width: 400px;
  height: 400px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(230,255,50,0.1) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content {
  text-align: center;
  max-width: 800px;
  margin: 0 auto 48px;
  position: relative;
  z-index: 1;
}
.hero h1 {
  margin-bottom: 20px;
}
.hero h1 .highlight {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}
.hero-subtitle {
  font-size: 1.2rem;
  color: var(--neutral-600);
  margin-bottom: 32px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}
.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Hero Tabs */
.hero-tabs {
  display: flex;
  justify-content: center;
  gap: 4px;
  margin-bottom: 24px;
  background: var(--neutral-100);
  border-radius: var(--radius-full);
  padding: 4px;
  width: fit-content;
  margin-left: auto;
  margin-right: auto;
}
.hero-tab {
  padding: 10px 24px;
  font-weight: 600;
  font-size: 0.9rem;
  border-radius: var(--radius-full);
  color: var(--neutral-500);
  transition: all var(--transition);
}
.hero-tab.active {
  background: var(--white);
  color: var(--primary);
  box-shadow: var(--shadow);
}
.hero-tab:hover:not(.active) {
  color: var(--neutral-700);
}

/* Hero Preview */
.hero-preview {
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  padding: 24px;
  max-width: 900px;
  margin: 0 auto;
  position: relative;
  z-index: 1;
  border: 1px solid var(--neutral-200);
}
.hero-preview-panel {
  display: none;
}
.hero-preview-panel.active {
  display: block;
  animation: fadeIn 0.4s ease;
}
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Mock Dashboard (Creator View) */
.mock-dashboard {
  border-radius: var(--radius);
  overflow: hidden;
}
.mock-dashboard-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  background: var(--neutral-900);
  color: var(--white);
}
.mock-dashboard-header .dot-group {
  display: flex;
  gap: 6px;
}
.mock-dashboard-header .dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}
.mock-dashboard-header .dot:nth-child(1) { background: #FF5F57; }
.mock-dashboard-header .dot:nth-child(2) { background: #FFBD2E; }
.mock-dashboard-header .dot:nth-child(3) { background: #28CA41; }
.mock-dashboard-body {
  display: grid;
  grid-template-columns: 200px 1fr;
  min-height: 320px;
  background: var(--neutral-50);
}
.mock-sidebar {
  background: var(--neutral-800);
  padding: 16px 12px;
  color: var(--neutral-300);
  font-size: 0.8rem;
}
.mock-sidebar-item {
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  margin-bottom: 4px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.mock-sidebar-item.active {
  background: var(--primary);
  color: var(--white);
}
.mock-sidebar-icon {
  width: 16px;
  height: 16px;
  border-radius: 3px;
  background: currentColor;
  opacity: 0.5;
}
.mock-sidebar-item.active .mock-sidebar-icon { opacity: 1; }
.mock-main {
  padding: 24px;
}
.mock-stat-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-bottom: 24px;
}
.mock-stat-card {
  background: var(--white);
  padding: 16px;
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
}
.mock-stat-card .label {
  font-size: 0.75rem;
  color: var(--neutral-500);
  margin-bottom: 4px;
}
.mock-stat-card .value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--neutral-900);
  font-family: var(--font-heading);
}
.mock-chart {
  background: var(--white);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: var(--shadow-sm);
}
.mock-chart-bars {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  height: 120px;
  margin-top: 12px;
}
.mock-chart-bar {
  flex: 1;
  border-radius: 4px 4px 0 0;
  background: linear-gradient(180deg, var(--primary-light) 0%, var(--primary) 100%);
  min-height: 20px;
}

/* Mock Student View */
.mock-student {
  border-radius: var(--radius);
  overflow: hidden;
}
.mock-student-header {
  background: var(--primary);
  padding: 16px 20px;
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.mock-student-body {
  padding: 24px;
  background: var(--neutral-50);
}
.mock-course-card {
  background: var(--white);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  margin-bottom: 16px;
  display: grid;
  grid-template-columns: 120px 1fr;
}
.mock-course-thumb {
  background: linear-gradient(135deg, var(--primary-200) 0%, var(--primary) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 2rem;
  min-height: 80px;
}
.mock-course-info {
  padding: 16px;
}
.mock-course-info h4 {
  font-size: 0.95rem;
  margin-bottom: 6px;
}
.mock-progress-bar {
  height: 6px;
  background: var(--neutral-200);
  border-radius: 3px;
  margin-top: 8px;
  overflow: hidden;
}
.mock-progress-fill {
  height: 100%;
  border-radius: 3px;
  background: linear-gradient(90deg, var(--primary) 0%, var(--green) 100%);
}
.mock-progress-label {
  font-size: 0.75rem;
  color: var(--neutral-500);
  margin-top: 4px;
}

/* --- Stats Bar --- */
.stats-bar {
  background: var(--neutral-900);
  padding: 40px 0;
}
.stats-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  text-align: center;
}
.stat-item {
  color: var(--white);
}
.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-dark) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  letter-spacing: -0.02em;
}
.stat-label {
  font-size: 0.95rem;
  color: var(--neutral-400);
  margin-top: 4px;
}

/* --- Product Cards --- */
.products-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}
.product-card {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--primary) 0%, var(--accent) 100%);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}
.product-card:hover {
  border-color: var(--primary-200);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}
.product-card:hover::before {
  transform: scaleX(1);
}
.product-card-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 16px;
}
.product-card-icon.courses { background: var(--primary-50); color: var(--primary); }
.product-card-icon.coaching { background: var(--coral-light); color: var(--coral); }
.product-card-icon.downloads { background: var(--green-light); color: var(--green); }
.product-card-icon.memberships { background: #FEF3C7; color: #D97706; }
.product-card h3 { margin-bottom: 8px; }
.product-card p { color: var(--neutral-500); font-size: 0.95rem; }
.product-card-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 16px;
  color: var(--primary);
  font-weight: 600;
  font-size: 0.9rem;
  transition: gap var(--transition);
}
.product-card-link:hover { gap: 10px; }

/* --- Why Choose Us (Tabs) --- */
.why-tabs {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin-bottom: 40px;
  background: var(--neutral-100);
  border-radius: var(--radius-full);
  padding: 6px;
  width: fit-content;
  margin-left: auto;
  margin-right: auto;
}
.why-tab {
  padding: 10px 20px;
  font-weight: 600;
  font-size: 0.85rem;
  border-radius: var(--radius-full);
  color: var(--neutral-500);
  transition: all var(--transition);
  white-space: nowrap;
}
.why-tab.active {
  background: var(--primary);
  color: var(--white);
  box-shadow: var(--shadow);
}
.why-tab:hover:not(.active) {
  color: var(--neutral-700);
}
.why-panel {
  display: none;
  animation: fadeIn 0.4s ease;
}
.why-panel.active { display: block; }
.why-features {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 20px;
}
.why-feature-item {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 16px;
  background: var(--primary-50);
  border-radius: var(--radius);
}
.why-feature-icon {
  width: 24px;
  height: 24px;
  border-radius: 6px;
  background: var(--primary);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  flex-shrink: 0;
  margin-top: 2px;
}
.why-feature-text {
  font-weight: 500;
  font-size: 0.95rem;
  color: var(--neutral-800);
}

/* --- Global Scale Section --- */
.global-scale {
  background: var(--neutral-900);
  color: var(--white);
  position: relative;
  overflow: hidden;
}
.global-scale::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 800px;
  height: 800px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.05);
  pointer-events: none;
}
.global-scale h2 { color: var(--white); }
.global-scale .subtitle { color: var(--neutral-400); }
.global-features {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}
.global-feature {
  text-align: center;
  padding: 32px;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-lg);
  background: rgba(255,255,255,0.03);
  transition: all var(--transition);
}
.global-feature:hover {
  border-color: rgba(255,255,255,0.2);
  background: rgba(255,255,255,0.06);
}
.global-feature-icon {
  font-size: 2.5rem;
  margin-bottom: 16px;
}
.global-feature h3 { color: var(--white); margin-bottom: 8px; }
.global-feature p { color: var(--neutral-400); font-size: 0.95rem; margin: 0 auto; }

/* --- AI Automations --- */
.ai-section {
  background: linear-gradient(180deg, var(--white) 0%, var(--primary-50) 100%);
}
.ai-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}
.ai-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 28px;
  border: 1px solid var(--neutral-200);
  transition: all var(--transition);
}
.ai-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--primary-200);
}
.ai-card-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius);
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  margin-bottom: 16px;
}
.ai-card h3 { margin-bottom: 8px; font-size: 1.1rem; }
.ai-card p { color: var(--neutral-500); font-size: 0.9rem; }

/* --- Testimonials Carousel --- */
.testimonials-section {
  background: var(--neutral-50);
}
.testimonials-carousel {
  position: relative;
  overflow: hidden;
}
.testimonials-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
.testimonial-card {
  min-width: 100%;
  padding: 0 12px;
}
.testimonial-inner {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px;
  box-shadow: var(--shadow);
  border: 1px solid var(--neutral-200);
  position: relative;
}
.testimonial-inner::before {
  content: '\201C';
  font-size: 4rem;
  color: var(--primary-200);
  position: absolute;
  top: 16px;
  left: 24px;
  line-height: 1;
  font-family: Georgia, serif;
}
.testimonial-quote {
  font-size: 1.1rem;
  color: var(--neutral-700);
  line-height: 1.7;
  margin-bottom: 24px;
  position: relative;
  z-index: 1;
  padding-top: 20px;
}
.testimonial-tag {
  display: inline-block;
  padding: 4px 14px;
  border-radius: var(--radius-full);
  background: var(--primary-50);
  color: var(--primary);
  font-weight: 600;
  font-size: 0.8rem;
  margin-bottom: 12px;
}
.testimonial-author {
  font-weight: 700;
  color: var(--neutral-900);
}
.testimonial-role {
  font-size: 0.85rem;
  color: var(--neutral-500);
}
.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}
.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--neutral-200);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--neutral-600);
  transition: all var(--transition);
  background: var(--white);
}
.carousel-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: var(--primary-50);
}
.carousel-dots {
  display: flex;
  gap: 8px;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--neutral-300);
  transition: all var(--transition);
  cursor: pointer;
}
.carousel-dot.active {
  background: var(--primary);
  width: 28px;
  border-radius: 5px;
}

/* --- Pricing Overview --- */
.pricing-overview {
  position: relative;
}
.pricing-note {
  text-align: center;
  margin-bottom: 48px;
  color: var(--neutral-500);
  font-size: 1rem;
}
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.pricing-card {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  padding: 28px;
  text-align: center;
  transition: all var(--transition);
  position: relative;
}
.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: 0 0 0 1px var(--primary), var(--shadow-lg);
}
.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  padding: 4px 16px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
}
.pricing-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}
.pricing-tier {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.1rem;
  margin-bottom: 4px;
  color: var(--neutral-900);
}
.pricing-price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 4px;
}
.pricing-price span {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--neutral-500);
}
.pricing-fee {
  font-size: 0.8rem;
  color: var(--green);
  font-weight: 600;
  margin-bottom: 20px;
}
.pricing-features {
  text-align: left;
  margin-bottom: 24px;
}
.pricing-features li {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 0;
  font-size: 0.85rem;
  color: var(--neutral-600);
}
.pricing-features li::before {
  content: '\2713';
  color: var(--green);
  font-weight: 700;
  flex-shrink: 0;
}
.pricing-card .btn {
  width: 100%;
}
.pricing-enterprise {
  margin-top: 32px;
  background: var(--neutral-900);
  border-radius: var(--radius-lg);
  padding: 40px;
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}
.pricing-enterprise h3 { color: var(--white); }
.pricing-enterprise p { color: var(--neutral-400); margin: 0; }
.pricing-enterprise-features {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}
.pricing-enterprise-features span {
  padding: 4px 12px;
  background: rgba(255,255,255,0.1);
  border-radius: var(--radius-full);
  font-size: 0.8rem;
  color: var(--neutral-300);
}

/* --- Integrations --- */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}
.integration-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 20px 12px;
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius);
  transition: all var(--transition);
}
.integration-item:hover {
  border-color: var(--primary-200);
  box-shadow: var(--shadow);
  transform: translateY(-2px);
}
.integration-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.75rem;
  color: var(--white);
}
.integration-item span {
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--neutral-600);
  text-align: center;
}

/* --- Social Proof --- */
.social-proof {
  text-align: center;
}
.social-proof-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 40px;
  margin-top: 32px;
}
.social-proof-logo {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--neutral-400);
  opacity: 0.6;
  transition: opacity var(--transition);
}
.social-proof-logo:hover { opacity: 1; }

/* --- FAQ Accordion --- */
.faq-section {
  background: var(--neutral-50);
}
.faq-list {
  max-width: 760px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid var(--neutral-200);
}
.faq-question {
  width: 100%;
  padding: 20px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 1rem;
  font-weight: 600;
  color: var(--neutral-900);
  text-align: left;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--primary); }
.faq-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 2px solid var(--neutral-300);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  flex-shrink: 0;
  margin-left: 16px;
}
.faq-item.open .faq-icon {
  background: var(--primary);
  border-color: var(--primary);
  color: var(--white);
  transform: rotate(45deg);
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}
.faq-answer-inner {
  padding-bottom: 20px;
  color: var(--neutral-600);
  font-size: 0.95rem;
  line-height: 1.7;
}

/* --- CTA Banner --- */
.cta-banner {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  border-radius: var(--radius-xl);
  padding: 64px 48px;
  text-align: center;
  color: var(--white);
  position: relative;
  overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute;
  top: -100px;
  right: -100px;
  width: 300px;
  height: 300px;
  border-radius: 50%;
  background: rgba(230,255,50,0.1);
  pointer-events: none;
}
.cta-banner h2 { color: var(--white); margin-bottom: 16px; }
.cta-banner p { color: rgba(255,255,255,0.85); margin: 0 auto 32px; font-size: 1.1rem; }
.cta-banner .btn-accent {
  font-size: 1.05rem;
  padding: 16px 36px;
}

/* --- Footer --- */
.footer {
  background: var(--neutral-900);
  color: var(--neutral-400);
  padding: 64px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}
.footer-brand p {
  color: var(--neutral-500);
  font-size: 0.9rem;
  margin-top: 16px;
  max-width: 280px;
}
.footer-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--white);
}
.footer-logo span { color: var(--accent); }
.footer-col h4 {
  color: var(--white);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 16px;
}
.footer-col a {
  display: block;
  padding: 4px 0;
  font-size: 0.9rem;
  color: var(--neutral-500);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8rem;
  color: var(--neutral-600);
}
.footer-bottom-links {
  display: flex;
  gap: 24px;
}
.footer-bottom-links a {
  color: var(--neutral-600);
  transition: color var(--transition);
}
.footer-bottom-links a:hover { color: var(--white); }

/* --- Feature Cards (shared across product pages) --- */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.feature-card {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}
.feature-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
  border-color: var(--primary-200);
}
.feature-card-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}
.feature-card-icon.blue { background: var(--primary-50); color: var(--primary); }
.feature-card-icon.coral { background: var(--coral-light); color: var(--coral); }
.feature-card-icon.green { background: var(--green-light); color: var(--green); }
.feature-card-icon.yellow { background: #FEF3C7; color: #D97706; }
.feature-card h3 { margin-bottom: 10px; }
.feature-card p { color: var(--neutral-500); font-size: 0.95rem; }

/* --- Tools Grid --- */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.tools-category {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  padding: 24px;
}
.tools-category-title {
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--primary);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.tools-list li {
  padding: 6px 0;
  font-size: 0.9rem;
  color: var(--neutral-600);
  display: flex;
  align-items: center;
  gap: 6px;
}
.tools-list li::before {
  content: '\2022';
  color: var(--primary-300);
  font-size: 0.7rem;
}

/* --- Three Steps --- */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  position: relative;
}
.steps-grid::before {
  content: '';
  position: absolute;
  top: 36px;
  left: calc(33.33% - 16px);
  right: calc(33.33% - 16px);
  height: 2px;
  background: var(--neutral-200);
  z-index: 0;
}
.step-card {
  text-align: center;
  position: relative;
  z-index: 1;
}
.step-number {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: var(--primary);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
  box-shadow: 0 0 0 8px var(--primary-100);
}
.step-card h3 { margin-bottom: 8px; }
.step-card p { color: var(--neutral-500); font-size: 0.95rem; margin: 0 auto; }

/* --- Value Proposition Cards --- */
.value-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.value-card {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}
.value-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}
.value-card-icon {
  font-size: 2rem;
  margin-bottom: 16px;
}
.value-card h3 { margin-bottom: 8px; }
.value-card p { color: var(--neutral-500); font-size: 0.95rem; }

/* --- File Types Grid --- */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.file-type-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px;
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius);
  transition: all var(--transition);
}
.file-type-card:hover {
  border-color: var(--primary-200);
  box-shadow: var(--shadow);
}
.file-type-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  background: var(--primary-50);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  flex-shrink: 0;
}
.file-type-card span {
  font-weight: 500;
  color: var(--neutral-700);
}

/* --- Resources Section --- */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.resource-card {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all var(--transition);
}
.resource-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
  border-color: var(--primary-200);
}
.resource-card-tag {
  display: inline-block;
  padding: 4px 12px;
  background: var(--primary-50);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  margin-bottom: 12px;
}
.resource-card h3 { font-size: 1.05rem; margin-bottom: 8px; }
.resource-card p { color: var(--neutral-500); font-size: 0.9rem; }
.resource-card-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 16px;
  color: var(--primary);
  font-weight: 600;
  font-size: 0.85rem;
}

/* --- Coaching Spotlight --- */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.spotlight-card {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition);
}
.spotlight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}
.spotlight-card-header {
  padding: 32px 28px 16px;
  background: linear-gradient(135deg, var(--primary-50) 0%, var(--primary-100) 100%);
}
.spotlight-card-header h3 { margin-bottom: 4px; }
.spotlight-card-header p { color: var(--primary); font-size: 0.9rem; font-weight: 500; }
.spotlight-card-body {
  padding: 20px 28px 28px;
}
.spotlight-card-body p { color: var(--neutral-500); font-size: 0.95rem; }

/* --- Business Fit Section --- */
.business-fit-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.business-fit-card {
  text-align: center;
  padding: 32px;
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  transition: all var(--transition);
}
.business-fit-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}
.business-fit-card-icon {
  font-size: 2.5rem;
  margin-bottom: 16px;
}
.business-fit-card h3 { margin-bottom: 8px; }
.business-fit-card p { color: var(--neutral-500); font-size: 0.95rem; margin: 0 auto; }

/* --- Product Demo Accordion --- */
.product-demo-section {
  background: var(--neutral-50);
}
.demo-accordion {
  max-width: 900px;
  margin: 0 auto;
}
.demo-accordion-item {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  margin-bottom: 16px;
  overflow: hidden;
  transition: all var(--transition);
}
.demo-accordion-item.open {
  box-shadow: var(--shadow-md);
  border-color: var(--primary-200);
}
.demo-accordion-trigger {
  width: 100%;
  padding: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--neutral-900);
  text-align: left;
}
.demo-accordion-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--primary-50);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  flex-shrink: 0;
  margin-left: 16px;
}
.demo-accordion-item.open .demo-accordion-icon {
  background: var(--primary);
  color: var(--white);
  transform: rotate(45deg);
}
.demo-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}
.demo-accordion-content-inner {
  padding: 0 24px 24px;
  color: var(--neutral-600);
  font-size: 0.95rem;
  line-height: 1.7;
}

/* --- Membership Stats --- */
.membership-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.membership-stat-card {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  text-align: center;
  transition: all var(--transition);
}
.membership-stat-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}
.membership-stat-value {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 8px;
}
.membership-stat-label {
  font-weight: 600;
  color: var(--neutral-800);
  margin-bottom: 6px;
}
.membership-stat-desc {
  font-size: 0.9rem;
  color: var(--neutral-500);
}

/* --- Section Headers --- */
.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 48px;
}
.section-header h2 { margin-bottom: 16px; }
.section-header .subtitle {
  font-size: 1.1rem;
  color: var(--neutral-500);
}
.section-badge {
  display: inline-block;
  padding: 6px 16px;
  border-radius: var(--radius-full);
  background: var(--primary-50);
  color: var(--primary);
  font-weight: 600;
  font-size: 0.8rem;
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .pricing-grid { grid-template-columns: repeat(2, 1fr); }
  .tools-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 2fr 1fr 1fr; }
  .footer-grid .footer-col:nth-child(4),
  .footer-grid .footer-col:nth-child(5) { grid-column: span 1; }
  .integrations-grid { grid-template-columns: repeat(4, 1fr); }
  .global-features { grid-template-columns: repeat(2, 1fr); }
  .ai-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  :root { --nav-height: 64px; }
  .section { padding: 60px 0; }
  .section-lg { padding: 72px 0; }

  .nav-links { display: none; }
  .nav-cta.desktop { display: none; }
  .nav-mobile-toggle { display: flex; }

  .hero { padding-top: calc(var(--nav-height) + 40px); padding-bottom: 40px; }
  .hero-subtitle { font-size: 1.05rem; }
  .hero-tabs { font-size: 0.85rem; }
  .hero-tab { padding: 8px 16px; font-size: 0.8rem; }

  .stats-grid { grid-template-columns: 1fr; gap: 24px; }
  .products-grid { grid-template-columns: 1fr; }
  .feature-grid { grid-template-columns: 1fr; }
