  font-size: 0.75rem;
  flex-shrink: 0;
  margin-top: 2px;
}
.why-feature-text {
  font-weight: 500;
  font-size: 0.95rem;
  color: var(--neutral-800);
}

/* --- Global Scale Section --- */
.global-scale {
  background: var(--neutral-900);
  color: var(--white);
  position: relative;
  overflow: hidden;
}
.global-scale::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 800px;
  height: 800px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.05);
  pointer-events: none;
}
.global-scale h2 { color: var(--white); }
.global-scale .subtitle { color: var(--neutral-400); }
.global-features {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}
.global-feature {
  text-align: center;
  padding: 32px;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-lg);
  background: rgba(255,255,255,0.03);
  transition: all var(--transition);
}
.global-feature:hover {
  border-color: rgba(255,255,255,0.2);
  background: rgba(255,255,255,0.06);
}
.global-feature-icon {
  font-size: 2.5rem;
  margin-bottom: 16px;
}
.global-feature h3 { color: var(--white); margin-bottom: 8px; }
.global-feature p { color: var(--neutral-400); font-size: 0.95rem; margin: 0 auto; }

/* --- AI Automations --- */
.ai-section {
  background: linear-gradient(180deg, var(--white) 0%, var(--primary-50) 100%);
}
.ai-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}
.ai-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 28px;
  border: 1px solid var(--neutral-200);
  transition: all var(--transition);
}
.ai-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  border-color: var(--primary-200);
}
.ai-card-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius);
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  margin-bottom: 16px;
}
.ai-card h3 { margin-bottom: 8px; font-size: 1.1rem; }
.ai-card p { color: var(--neutral-500); font-size: 0.9rem; }

/* --- Testimonials Carousel --- */
.testimonials-section {
  background: var(--neutral-50);
}
.testimonials-carousel {
  position: relative;
  overflow: hidden;
}
.testimonials-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
.testimonial-card {
  min-width: 100%;
  padding: 0 12px;
}
.testimonial-inner {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px;
  box-shadow: var(--shadow);
  border: 1px solid var(--neutral-200);
  position: relative;
}
.testimonial-inner::before {
  content: '\201C';
  font-size: 4rem;
  color: var(--primary-200);
  position: absolute;
  top: 16px;
  left: 24px;
  line-height: 1;
  font-family: Georgia, serif;
}
.testimonial-quote {
  font-size: 1.1rem;
  color: var(--neutral-700);
  line-height: 1.7;
  margin-bottom: 24px;
  position: relative;
  z-index: 1;
  padding-top: 20px;
}
.testimonial-tag {
  display: inline-block;
  padding: 4px 14px;
  border-radius: var(--radius-full);
  background: var(--primary-50);
  color: var(--primary);
  font-weight: 600;
  font-size: 0.8rem;
  margin-bottom: 12px;
}
.testimonial-author {
  font-weight: 700;
  color: var(--neutral-900);
}
.testimonial-role {
  font-size: 0.85rem;
  color: var(--neutral-500);
}
.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}
.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--neutral-200);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--neutral-600);
  transition: all var(--transition);
  background: var(--white);
}
.carousel-btn:hover {
  border-color: var(--primary);
  color: var(--primary);
  background: var(--primary-50);
}
.carousel-dots {
  display: flex;
  gap: 8px;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--neutral-300);
  transition: all var(--transition);
  cursor: pointer;
}
.carousel-dot.active {
  background: var(--primary);
  width: 28px;
  border-radius: 5px;
}

/* --- Pricing Overview --- */
.pricing-overview {
  position: relative;
}
.pricing-note {
  text-align: center;
  margin-bottom: 48px;
  color: var(--neutral-500);
  font-size: 1rem;
}
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}
.pricing-card {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  padding: 28px;
  text-align: center;
  transition: all var(--transition);
  position: relative;
}
.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: 0 0 0 1px var(--primary), var(--shadow-lg);
}
.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  padding: 4px 16px;
  border-radius: var(--radius-full);
  font-size: 0.75rem;
  font-weight: 700;
}
.pricing-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}
.pricing-tier {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.1rem;
  margin-bottom: 4px;
  color: var(--neutral-900);
}
.pricing-price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 4px;
}
.pricing-price span {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--neutral-500);
}
.pricing-fee {
  font-size: 0.8rem;
  color: var(--green);
  font-weight: 600;
  margin-bottom: 20px;
}
.pricing-features {
  text-align: left;
  margin-bottom: 24px;
}
.pricing-features li {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 0;
  font-size: 0.85rem;
  color: var(--neutral-600);
}
.pricing-features li::before {
  content: '\2713';
  color: var(--green);
  font-weight: 700;
  flex-shrink: 0;
}
.pricing-card .btn {
  width: 100%;
}
.pricing-enterprise {
  margin-top: 32px;
  background: var(--neutral-900);
  border-radius: var(--radius-lg);
  padding: 40px;
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}
.pricing-enterprise h3 { color: var(--white); }
.pricing-enterprise p { color: var(--neutral-400); margin: 0; }
.pricing-enterprise-features {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}
.pricing-enterprise-features span {
  padding: 4px 12px;
  background: rgba(255,255,255,0.1);
  border-radius: var(--radius-full);
  font-size: 0.8rem;
  color: var(--neutral-300);
}

/* --- Integrations --- */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}
.integration-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 20px 12px;
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius);
  transition: all var(--transition);
}
.integration-item:hover {
  border-color: var(--primary-200);
  box-shadow: var(--shadow);
  transform: translateY(-2px);
}
.integration-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.75rem;
  color: var(--white);
}
.integration-item span {
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--neutral-600);
  text-align: center;
}

/* --- Social Proof --- */
.social-proof {
  text-align: center;
}
.social-proof-logos {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 40px;
  margin-top: 32px;
}
.social-proof-logo {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--neutral-400);
  opacity: 0.6;
  transition: opacity var(--transition);
}
.social-proof-logo:hover { opacity: 1; }

/* --- FAQ Accordion --- */
.faq-section {
  background: var(--neutral-50);
}
.faq-list {
  max-width: 760px;
  margin: 0 auto;
}
.faq-item {
  border-bottom: 1px solid var(--neutral-200);
}
.faq-question {
  width: 100%;
  padding: 20px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 1rem;
  font-weight: 600;
  color: var(--neutral-900);
  text-align: left;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--primary); }
.faq-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 2px solid var(--neutral-300);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  flex-shrink: 0;
  margin-left: 16px;
}
.faq-item.open .faq-icon {
  background: var(--primary);
  border-color: var(--primary);
  color: var(--white);
  transform: rotate(45deg);
}
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}
.faq-answer-inner {
  padding-bottom: 20px;
  color: var(--neutral-600);
  font-size: 0.95rem;
  line-height: 1.7;
}

/* --- CTA Banner --- */
.cta-banner {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  border-radius: var(--radius-xl);
  padding: 64px 48px;
  text-align: center;
  color: var(--white);
  position: relative;
  overflow: hidden;
}
.cta-banner::before {
  content: '';
  position: absolute;
  top: -100px;
  right: -100px;
  width: 300px;
  height: 300px;
  border-radius: 50%;
  background: rgba(230,255,50,0.1);
  pointer-events: none;
}
.cta-banner h2 { color: var(--white); margin-bottom: 16px; }
.cta-banner p { color: rgba(255,255,255,0.85); margin: 0 auto 32px; font-size: 1.1rem; }
.cta-banner .btn-accent {
  font-size: 1.05rem;
  padding: 16px 36px;
}

/* --- Footer --- */
.footer {
  background: var(--neutral-900);
  color: var(--neutral-400);
  padding: 64px 0 32px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}
.footer-brand p {
  color: var(--neutral-500);
  font-size: 0.9rem;
  margin-top: 16px;
  max-width: 280px;
}
.footer-logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--white);
}
.footer-logo span { color: var(--accent); }
.footer-col h4 {
  color: var(--white);
  font-size: 0.85rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 16px;
}
.footer-col a {
  display: block;
  padding: 4px 0;
  font-size: 0.9rem;
  color: var(--neutral-500);
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--white); }
.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8rem;
  color: var(--neutral-600);
}
.footer-bottom-links {
  display: flex;
  gap: 24px;
}
.footer-bottom-links a {
  color: var(--neutral-600);
  transition: color var(--transition);
}
.footer-bottom-links a:hover { color: var(--white); }

/* --- Feature Cards (shared across product pages) --- */
.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.feature-card {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}
.feature-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
  border-color: var(--primary-200);
}
.feature-card-icon {
  width: 52px;
  height: 52px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}
.feature-card-icon.blue { background: var(--primary-50); color: var(--primary); }
.feature-card-icon.coral { background: var(--coral-light); color: var(--coral); }
.feature-card-icon.green { background: var(--green-light); color: var(--green); }
.feature-card-icon.yellow { background: #FEF3C7; color: #D97706; }
.feature-card h3 { margin-bottom: 10px; }
.feature-card p { color: var(--neutral-500); font-size: 0.95rem; }

/* --- Tools Grid --- */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}
.tools-category {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  padding: 24px;
}
.tools-category-title {
  font-weight: 700;
  font-size: 0.95rem;
  color: var(--primary);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}
.tools-list li {
  padding: 6px 0;
  font-size: 0.9rem;
  color: var(--neutral-600);
  display: flex;
  align-items: center;
  gap: 6px;
}
.tools-list li::before {
  content: '\2022';
  color: var(--primary-300);
  font-size: 0.7rem;
}

/* --- Three Steps --- */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  position: relative;
}
.steps-grid::before {
  content: '';
  position: absolute;
  top: 36px;
  left: calc(33.33% - 16px);
  right: calc(33.33% - 16px);
  height: 2px;
  background: var(--neutral-200);
  z-index: 0;
}
.step-card {
  text-align: center;
  position: relative;
  z-index: 1;
}
.step-number {
  width: 72px;
  height: 72px;
  border-radius: 50%;
  background: var(--primary);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 20px;
  box-shadow: 0 0 0 8px var(--primary-100);
}
.step-card h3 { margin-bottom: 8px; }
.step-card p { color: var(--neutral-500); font-size: 0.95rem; margin: 0 auto; }

/* --- Value Proposition Cards --- */
.value-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.value-card {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}
.value-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}
.value-card-icon {
  font-size: 2rem;
  margin-bottom: 16px;
}
.value-card h3 { margin-bottom: 8px; }
.value-card p { color: var(--neutral-500); font-size: 0.95rem; }

/* --- File Types Grid --- */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.file-type-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px;
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius);
  transition: all var(--transition);
}
.file-type-card:hover {
  border-color: var(--primary-200);
  box-shadow: var(--shadow);
}
.file-type-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--radius-sm);
  background: var(--primary-50);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.2rem;
  flex-shrink: 0;
}
.file-type-card span {
  font-weight: 500;
  color: var(--neutral-700);
}

/* --- Resources Section --- */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.resource-card {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: all var(--transition);
}
.resource-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
  border-color: var(--primary-200);
}
.resource-card-tag {
  display: inline-block;
  padding: 4px 12px;
  background: var(--primary-50);
  color: var(--primary);
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: var(--radius-full);
  margin-bottom: 12px;
}
.resource-card h3 { font-size: 1.05rem; margin-bottom: 8px; }
.resource-card p { color: var(--neutral-500); font-size: 0.9rem; }
.resource-card-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 16px;
  color: var(--primary);
  font-weight: 600;
  font-size: 0.85rem;
}

/* --- Coaching Spotlight --- */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.spotlight-card {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition);
}
.spotlight-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}
.spotlight-card-header {
  padding: 32px 28px 16px;
  background: linear-gradient(135deg, var(--primary-50) 0%, var(--primary-100) 100%);
}
.spotlight-card-header h3 { margin-bottom: 4px; }
.spotlight-card-header p { color: var(--primary); font-size: 0.9rem; font-weight: 500; }
.spotlight-card-body {
  padding: 20px 28px 28px;
}
.spotlight-card-body p { color: var(--neutral-500); font-size: 0.95rem; }

/* --- Business Fit Section --- */
.business-fit-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.business-fit-card {
  text-align: center;
  padding: 32px;
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  transition: all var(--transition);
}
.business-fit-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}
.business-fit-card-icon {
  font-size: 2.5rem;
  margin-bottom: 16px;
}
.business-fit-card h3 { margin-bottom: 8px; }
.business-fit-card p { color: var(--neutral-500); font-size: 0.95rem; margin: 0 auto; }

/* --- Product Demo Accordion --- */
.product-demo-section {
  background: var(--neutral-50);
}
.demo-accordion {
  max-width: 900px;
  margin: 0 auto;
}
.demo-accordion-item {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  margin-bottom: 16px;
  overflow: hidden;
  transition: all var(--transition);
}
.demo-accordion-item.open {
  box-shadow: var(--shadow-md);
  border-color: var(--primary-200);
}
.demo-accordion-trigger {
  width: 100%;
  padding: 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--neutral-900);
  text-align: left;
}
.demo-accordion-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--primary-50);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
  flex-shrink: 0;
  margin-left: 16px;
}
.demo-accordion-item.open .demo-accordion-icon {
  background: var(--primary);
  color: var(--white);
  transform: rotate(45deg);
}
.demo-accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}
.demo-accordion-content-inner {
  padding: 0 24px 24px;
  color: var(--neutral-600);
  font-size: 0.95rem;
  line-height: 1.7;
}

/* --- Membership Stats --- */
.membership-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.membership-stat-card {
  background: var(--white);
  border: 1px solid var(--neutral-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  text-align: center;
  transition: all var(--transition);
}
.membership-stat-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}
.membership-stat-value {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 8px;
}
.membership-stat-label {
  font-weight: 600;
  color: var(--neutral-800);
  margin-bottom: 6px;
}
.membership-stat-desc {
  font-size: 0.9rem;
  color: var(--neutral-500);
}

/* --- Section Headers --- */
.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 48px;
}
.section-header h2 { margin-bottom: 16px; }
.section-header .subtitle {
  font-size: 1.1rem;
  color: var(--neutral-500);
}
.section-badge {
  display: inline-block;
  padding: 6px 16px;
  border-radius: var(--radius-full);
  background: var(--primary-50);
  color: var(--primary);
  font-weight: 600;
  font-size: 0.8rem;
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* --- Responsive --- */
@media (max-width: 1024px) {
  .pricing-grid { grid-template-columns: repeat(2, 1fr); }
  .tools-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-grid { grid-template-columns: 2fr 1fr 1fr; }
  .footer-grid .footer-col:nth-child(4),
  .footer-grid .footer-col:nth-child(5) { grid-column: span 1; }
  .integrations-grid { grid-template-columns: repeat(4, 1fr); }
  .global-features { grid-template-columns: repeat(2, 1fr); }
  .ai-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  :root { --nav-height: 64px; }
  .section { padding: 60px 0; }
  .section-lg { padding: 72px 0; }

  .nav-links { display: none; }
  .nav-cta.desktop { display: none; }
  .nav-mobile-toggle { display: flex; }

  .hero { padding-top: calc(var(--nav-height) + 40px); padding-bottom: 40px; }
  .hero-subtitle { font-size: 1.05rem; }
  .hero-tabs { font-size: 0.85rem; }
  .hero-tab { padding: 8px 16px; font-size: 0.8rem; }

  .stats-grid { grid-template-columns: 1fr; gap: 24px; }
  .products-grid { grid-template-columns: 1fr; }
  .feature-grid { grid-template-columns: 1fr; }
  .value-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr; }
  .steps-grid::before { display: none; }
  .membership-stats { grid-template-columns: 1fr; }
  .spotlight-grid { grid-template-columns: 1fr; }
  .resources-grid { grid-template-columns: 1fr; }
  .file-types-grid { grid-template-columns: 1fr; }
  .business-fit-grid { grid-template-columns: 1fr; }
  .pricing-grid { grid-template-columns: 1fr; }
  .tools-grid { grid-template-columns: 1fr 1fr; }
  .integrations-grid { grid-template-columns: repeat(3, 1fr); }
  .why-features { grid-template-columns: 1fr; }
  .global-features { grid-template-columns: 1fr; }
  .ai-grid { grid-template-columns: 1fr; }

  .mock-dashboard-body { grid-template-columns: 1fr; }
  .mock-sidebar { display: none; }
  .mock-stat-row { grid-template-columns: 1fr; }
  .mock-course-card { grid-template-columns: 1fr; }

  .testimonial-inner { padding: 28px 20px; }
  .pricing-enterprise { flex-direction: column; text-align: center; }
  .cta-banner { padding: 48px 24px; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; gap: 12px; text-align: center; }

  .why-tabs { overflow-x: auto; flex-wrap: nowrap; justify-content: flex-start; margin-left: -24px; margin-right: -24px; padding-left: 24px; padding-right: 24px; width: calc(100% + 48px); }
  .why-tab { flex-shrink: 0; }
}

@media (max-width: 480px) {
  .hero-actions { flex-direction: column; width: 100%; }
  .hero-actions .btn { width: 100%; }
  .hero-preview { padding: 16px; }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }
  .tools-grid { grid-template-columns: 1fr; }
}

/* --- Utility Animations --- */
@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}
@keyframes slideUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-slide-up {
  animation: slideUp 0.6s ease forwards;
}
